fn ast2obj_expr_context(state: *mut ast_state, o: u32) -> *mut _object {
    match o as u32 {
        1 => {
            return Py_NewRef!(unsafe { (*state).Load_singleton });
        }
        2 => {
            return Py_NewRef!(unsafe { (*state).Store_singleton });
        }
        3 => {
            return Py_NewRef!(unsafe { (*state).Del_singleton });
        }
        _ => {}
    }
    Py_UNREACHABLE!();
    unsafe { core::mem::zeroed() }
}

